    function justifyText(text, y) {
      const lineHeight = 4;
      const marginRight = 10;
      const x = 10;

      let words = text.split(" ");
      let line = "";
      for (let i = 0; i < words.length; i++) {
        let testLine = line + words[i] + " ";
        let testWidth =
          (doc.getStringUnitWidth(testLine) * fontSize) /
          doc.internal.scaleFactor;
        if (testWidth > doc.internal.pageSize.width - x - marginRight) {
          doc.text(x, y, line, null, null, "justify");
          line = words[i] + " ";
          y += lineHeight;
        } else {
          line = testLine;
        }
      }
      doc.text(x, y, line, null, null, "justify");
    }

